//! Pruning tables: the cocsep (corner) table and the big H48 table.
//!
//! A pruning table maps a coordinate of the cube to a lower bound on its
//! distance to solved. IDA* (see `solver`) prunes a node when its bound
//! exceeds the moves left. Two tables are used:
//!
//! * `Cocsep`: the exact distance of each cocsep coordinate (corners only),
//!   plus its symmetry class, built at startup in a fraction of a second.
//! * `H48Table`: the distance of the full H48 coordinate (corner class,
//!   msplit, eo, eslot; see `coord`), 2 bits per entry, generated by `gen`
//!   and loaded from a file (58 GiB for h11).

use crate::coord::{cocsep, h11_key, reduce_key, N_CLASSES, N_COCSEP, N_MSPLIT, N_SLOTS};
use crate::simd::Cube;
use std::sync::atomic::{AtomicU64, Ordering};

// ---------------------------------------------------------------------------
// cocsep data
// ---------------------------------------------------------------------------

/// The cocsep table: per cocsep coordinate, its symmetry class, the
/// symmetry that maps it to the class representative ("sym to rep") and its
/// depth (distance to solved).
pub struct Cocsep {
    /// `entries[cocsep] = class << 16 | sym_to_rep << 8 | depth` (see
    /// `entry_*`).
    pub entries: Vec<u32>,
    /// Representative cube (corners only meaningful) per class.
    pub representatives: Vec<Cube>,
    /// Bitmask of the symmetries fixing the representative's cocsep, per
    /// class.
    pub self_symmetries: Vec<u64>,
    /// Depth distribution of the 153090 cocsep coordinates.
    pub distribution: Vec<u64>,
    /// Hot-path copy of `entries` packed into 3 bytes per entry (25% less
    /// L2 footprint): `class << 10 | sym_to_rep << 4 | depth` (+1 pad byte),
    /// on a transparent huge page (one TLB entry instead of ~113).
    packed: Memory,
}

/// Class of a packed cocsep entry (`Cocsep::packed`).
#[must_use]
#[inline(always)]
pub fn packed_class(packed: u32) -> usize {
    ((packed >> 10) & 0xFFF) as usize
}
/// Symmetry to the class representative of a packed cocsep entry.
#[must_use]
#[inline(always)]
pub fn packed_sym_to_rep(packed: u32) -> usize {
    ((packed >> 4) & 0x3F) as usize
}
/// Depth of a packed cocsep entry.
#[must_use]
#[inline(always)]
pub fn packed_depth(packed: u32) -> u8 {
    (packed & 15) as u8
}

/// Class of a cocsep entry (`Cocsep::entries`).
#[must_use]
#[inline(always)]
pub fn entry_class(entry: u32) -> usize {
    (entry >> 16) as usize
}
/// Symmetry to the class representative of a cocsep entry.
#[must_use]
#[inline(always)]
pub fn entry_sym_to_rep(entry: u32) -> usize {
    ((entry >> 8) & 0xFF) as usize
}
/// Depth of a cocsep entry.
#[must_use]
#[inline(always)]
pub fn entry_depth(entry: u32) -> u8 {
    (entry & 0xFF) as u8
}

impl Cocsep {
    /// Build the table: a breadth-first search (BFS) over the cocsep
    /// coordinate, then the symmetry classes.
    ///
    /// # Panics
    /// If the BFS does not find the expected number of coordinates or
    /// classes (a bug in the cube model).
    #[must_use]
    pub fn generate() -> Cocsep {
        // BFS over the cocsep coordinate, keeping a cube for each.
        let mut depth = vec![0xFFu8; N_COCSEP];
        let mut cube_of = vec![Cube::solved(); N_COCSEP];
        let mut order = Vec::with_capacity(N_COCSEP);
        let solved = cocsep(Cube::solved());
        depth[solved] = 0;
        order.push(solved);
        let mut head = 0;
        while head < order.len() {
            let i = order[head];
            head += 1;
            for mv in 0..18 {
                let next = cube_of[i].apply_move(mv);
                let j = cocsep(next);
                if depth[j] == 0xFF {
                    depth[j] = depth[i] + 1;
                    cube_of[j] = next;
                    order.push(j);
                }
            }
        }
        assert_eq!(order.len(), N_COCSEP);
        let mut distribution = vec![0u64; 16];
        for &d in &depth {
            distribution[usize::from(d)] += 1;
        }
        // Classes, in BFS order: the first coordinate of a class is its
        // representative; its 48 conjugates are the class's members.
        let mut class = vec![u32::MAX; N_COCSEP];
        let mut sym_to_rep = vec![0u8; N_COCSEP];
        let mut representatives = Vec::new();
        let mut self_symmetries = Vec::new();
        for &i in &order {
            if class[i] != u32::MAX {
                continue;
            }
            let new_class = u32::try_from(representatives.len()).unwrap();
            let rep = cube_of[i];
            let mut fixing = 0u64;
            for (sym, &inverse) in crate::simd::SYM_INVERSES.iter().enumerate() {
                let j = cocsep(rep.transform(sym));
                if class[j] == u32::MAX {
                    class[j] = new_class;
                    sym_to_rep[j] = inverse;
                }
                if j == i {
                    fixing |= 1 << sym;
                }
            }
            debug_assert_eq!(sym_to_rep[i], 0);
            representatives.push(rep);
            self_symmetries.push(fixing);
        }
        assert_eq!(representatives.len(), N_CLASSES);
        let entries: Vec<u32> = (0..N_COCSEP)
            .map(|i| (class[i] << 16) | (u32::from(sym_to_rep[i]) << 8) | u32::from(depth[i]))
            .collect();
        // 2 MiB: the kernel aligns it so that it gets one huge page.
        let packed = Memory::anonymous(2 << 20);
        let bytes = unsafe { std::slice::from_raw_parts_mut(packed.ptr(), 3 * N_COCSEP + 1) };
        for i in 0..N_COCSEP {
            assert!(depth[i] < 16);
            let entry = (class[i] << 10) | (u32::from(sym_to_rep[i]) << 4) | u32::from(depth[i]);
            bytes[3 * i..3 * i + 3].copy_from_slice(&entry.to_le_bytes()[..3]);
        }
        Cocsep {
            entries,
            representatives,
            self_symmetries,
            distribution,
            packed,
        }
    }

    /// A cheap stand-in for unit tests: corner depths from a BFS cut after
    /// `depth` moves (deeper coordinates get `depth + 1`, still a lower bound
    /// and still a function of the coset), all in one class with no symmetry.
    #[cfg(test)]
    pub(crate) fn truncated(depth: u8) -> Cocsep {
        let mut depths = vec![depth + 1; N_COCSEP];
        depths[cocsep(Cube::solved())] = 0;
        let mut frontier = vec![Cube::solved()];
        for d in 1..=depth {
            let mut next = Vec::new();
            for cube in frontier {
                for mv in 0..18 {
                    let child = cube.apply_move(mv);
                    let coord = cocsep(child);
                    if depths[coord] > d {
                        depths[coord] = d;
                        next.push(child);
                    }
                }
            }
            frontier = next;
        }
        // Packed entries `class << 10 | sym_to_rep << 4 | depth` with class
        // and sym_to_rep 0: just the depth byte.
        let packed = Memory::anonymous(2 << 20);
        let bytes = unsafe { std::slice::from_raw_parts_mut(packed.ptr(), 3 * N_COCSEP + 1) };
        let mut distribution = vec![0u64; 16];
        for (i, &d) in depths.iter().enumerate() {
            bytes[3 * i] = d;
            distribution[usize::from(d)] += 1;
        }
        Cocsep {
            entries: depths.iter().map(|&d| u32::from(d)).collect(),
            representatives: vec![Cube::solved(); N_CLASSES],
            self_symmetries: vec![1; N_CLASSES],
            distribution,
            packed,
        }
    }

    /// Base of the packed entries (see `packed`).
    #[must_use]
    pub fn packed_ptr(&self) -> *const u8 {
        self.packed.ptr()
    }

    /// Packed entry of cocsep coordinate `i` (see `packed_*`): a 4-byte
    /// unaligned load of 3 bytes and the next entry's first byte.
    #[must_use]
    #[inline(always)]
    pub fn packed(&self, i: usize) -> u32 {
        debug_assert!(i < N_COCSEP);
        unsafe { self.packed.ptr().add(3 * i).cast::<u32>().read_unaligned() }
    }

    /// Full h11 key of a cube (the reference path; the solver's hot path is
    /// `Solver::index`).
    #[must_use]
    #[inline(always)]
    pub fn full_key(&self, cube: Cube) -> u64 {
        let entry = unsafe { *self.entries.get_unchecked(cocsep(cube)) };
        let edges = cube.transform_edges(entry_sym_to_rep(entry));
        h11_key(entry_class(entry), edges)
    }

    /// hk table index of a cube.
    #[must_use]
    #[inline(always)]
    pub fn index(&self, cube: Cube, k: u32) -> u64 {
        reduce_key(self.full_key(cube), k)
    }
}

// ---------------------------------------------------------------------------
// Memory backing for huge tables
// ---------------------------------------------------------------------------

/// A memory mapping (anonymous or of a file), unmapped on drop.
pub struct Memory {
    ptr: *mut u8,
    len: usize,
}
// (A plain block of memory: shared read-only, or written with atomics.)
unsafe impl Send for Memory {}
unsafe impl Sync for Memory {}

impl Memory {
    /// Anonymous zeroed memory, transparent huge pages requested.
    ///
    /// # Panics
    /// If `mmap` fails.
    #[must_use]
    pub fn anonymous(len: usize) -> Memory {
        // (Miri supports only these flags, and no `madvise`.)
        #[cfg(not(miri))]
        let flags = libc::MAP_PRIVATE | libc::MAP_ANONYMOUS | libc::MAP_NORESERVE;
        #[cfg(miri)]
        let flags = libc::MAP_PRIVATE | libc::MAP_ANONYMOUS;
        unsafe {
            let p = libc::mmap(
                std::ptr::null_mut(),
                len,
                libc::PROT_READ | libc::PROT_WRITE,
                flags,
                -1,
                0,
            );
            assert!(p != libc::MAP_FAILED, "mmap failed");
            #[cfg(not(miri))]
            libc::madvise(p, len, libc::MADV_HUGEPAGE);
            Memory {
                ptr: p.cast::<u8>(),
                len,
            }
        }
    }

    /// Shared mapping of a file (e.g. on hugetlbfs, which gives 1GB pages).
    /// If `create`, the file is created/truncated to `len` and mapped
    /// writable, else mapped read-only.
    ///
    /// # Errors
    /// If the file cannot be opened, sized or mapped, or is shorter than
    /// `len`.
    pub fn map_file(path: &str, len: usize, create: bool) -> std::io::Result<Memory> {
        use std::os::unix::io::AsRawFd;
        // (Opened tables are mapped read-only: a stray write faults instead
        // of corrupting the shared table file for every process.)
        let file = std::fs::OpenOptions::new()
            .read(true)
            .write(create)
            .create(create)
            .truncate(false)
            .open(path)?;
        if create {
            // hugetlbfs needs the size rounded up to the page size.
            let page = 1usize << 30;
            let rounded = if path.contains("huge") {
                len.div_ceil(page) * page
            } else {
                len
            };
            file.set_len(rounded as u64)?;
        }
        let file_len = usize::try_from(file.metadata()?.len()).map_err(std::io::Error::other)?;
        if file_len < len {
            return Err(std::io::Error::other(format!(
                "table file {path} too small: {file_len} < {len}"
            )));
        }
        unsafe {
            let p = libc::mmap(
                std::ptr::null_mut(),
                file_len,
                if create {
                    libc::PROT_READ | libc::PROT_WRITE
                } else {
                    libc::PROT_READ
                },
                libc::MAP_SHARED | libc::MAP_POPULATE,
                file.as_raw_fd(),
                0,
            );
            if p == libc::MAP_FAILED {
                return Err(std::io::Error::last_os_error());
            }
            libc::madvise(p, file_len, libc::MADV_HUGEPAGE);
            Ok(Memory {
                ptr: p.cast::<u8>(),
                len: file_len,
            })
        }
    }

    #[must_use]
    pub fn ptr(&self) -> *mut u8 {
        self.ptr
    }
    #[must_use]
    pub fn len(&self) -> usize {
        self.len
    }
    #[must_use]
    pub fn is_empty(&self) -> bool {
        self.len == 0
    }
    /// The memory as 64-bit words, for the table generator's atomic updates.
    #[must_use]
    #[expect(clippy::cast_ptr_alignment, reason = "mappings are page aligned")]
    pub fn words(&self) -> &[AtomicU64] {
        unsafe { std::slice::from_raw_parts(self.ptr.cast::<AtomicU64>(), self.len / 8) }
    }
    #[must_use]
    pub fn bytes(&self) -> &[u8] {
        unsafe { std::slice::from_raw_parts(self.ptr, self.len) }
    }
}

impl Drop for Memory {
    fn drop(&mut self) {
        unsafe {
            libc::munmap(self.ptr.cast::<libc::c_void>(), self.len);
        }
    }
}

// ---------------------------------------------------------------------------
// H48 table (cube48opt layout): 128-byte rows of 512 2-bit slots, one row
// per (class, msplit, eoK); the row is indexed by eslot. Each 16-byte group
// (64 slots) reserves slots 0-1 for a 4-bit minimum over the group.
// ---------------------------------------------------------------------------

pub const ROW_BYTES: u64 = 128;
pub const WORDS_PER_ROW: usize = 16;

/// Rows of table hk: one per (class, msplit, top `k` eo bits).
#[must_use]
pub fn h48_rows(k: u32) -> u64 {
    (N_CLASSES * N_MSPLIT) as u64 * (1u64 << k)
}
/// Size of the index space (including unused slots).
#[must_use]
pub fn h48_slots(k: u32) -> u64 {
    h48_rows(k) * N_SLOTS as u64
}
/// Size of table hk in bytes.
#[must_use]
pub fn h48_bytes(k: u32) -> u64 {
    h48_rows(k) * ROW_BYTES
}

/// Default base value per h (cube48opt: 7 for h0, 8 for h2-3, 9 for h4-7, 10 above).
#[must_use]
pub fn default_base(k: u32) -> u8 {
    [7, 8, 8, 8, 9, 9, 9, 9, 10, 10, 10, 10][k as usize]
}

/// u64 word index and bit shift of an entry.
#[must_use]
#[inline(always)]
pub fn entry_position(index: u64) -> (usize, u32) {
    ((index >> 5) as usize, (index & 31) as u32 * 2)
}

/// Mask of the low bits of the 2-bit slots of word `w` that are real
/// entries.
#[must_use]
#[inline(always)]
pub fn entry_low_bits(w: u64) -> u64 {
    let mut mask = 0x5555_5555_5555_5555u64;
    if w.is_multiple_of(2) {
        mask &= !0x5; // slots 0, 1: group minimum
    }
    if w % WORDS_PER_ROW as u64 == WORDS_PER_ROW as u64 - 1 {
        mask &= !(1 << 62); // slot 511 unused
    }
    mask
}

/// Which table a file holds: `k` (of hk) and the `base` of its codes.
#[derive(Clone, Copy, Debug)]
pub struct H48Meta {
    pub k: u32,
    pub base: u8,
}

/// An H48 table: 2-bit codes, 0 = "at most `base`" (then the group minimum
/// and the corner depth give a bound), 1..=3 = `base + code` (3: at least).
pub struct H48Table {
    pub memory: Memory,
    pub meta: H48Meta,
}

impl H48Table {
    #[must_use]
    #[inline(always)]
    pub fn ptr(&self) -> *const u8 {
        self.memory.ptr()
    }

    /// Returns (2-bit code, group minimum).
    #[must_use]
    #[inline(always)]
    #[expect(clippy::cast_ptr_alignment, reason = "tables are page aligned")]
    pub fn get(&self, index: u64) -> (u8, u8) {
        unsafe {
            let words = self.memory.ptr().cast_const().cast::<u64>();
            let w = (index >> 5) as usize;
            let word = *words.add(w);
            // (The group's first word holds the minimum in slots 0-1.)
            let group_min = *words.add(w & !1) & 15;
            (((word >> ((index & 31) * 2)) & 3) as u8, group_min as u8)
        }
    }

    #[inline(always)]
    pub fn prefetch(&self, index: u64) {
        unsafe {
            let line = self.memory.ptr().add((index >> 2) as usize);
            // NTA: each line is read once; less L2 pollution (cocsep data).
            std::arch::x86_64::_mm_prefetch(line.cast::<i8>(), std::arch::x86_64::_MM_HINT_NTA);
        }
    }

    /// Distribution of the 2-bit codes over real entries.
    ///
    /// # Panics
    /// If a counting thread panics.
    #[must_use]
    pub fn distribution(&self) -> [u64; 4] {
        let len = usize::try_from(h48_bytes(self.meta.k) / 8).expect("64-bit usize");
        let words = &self.memory.words()[..len];
        let per_thread = len.div_ceil(crate::thread_count());
        let mut total = [0u64; 4];
        std::thread::scope(|s| {
            let handles: Vec<_> = words
                .chunks(per_thread)
                .enumerate()
                .map(|(t, chunk)| {
                    s.spawn(move || {
                        let mut counts = [0u64; 4];
                        for (w, word) in ((t * per_thread) as u64..).zip(chunk) {
                            let bits = word.load(Ordering::Relaxed);
                            let mask = entry_low_bits(w);
                            let lo = bits & mask;
                            let hi = (bits >> 1) & mask;
                            counts[3] += u64::from((lo & hi).count_ones());
                            counts[2] += u64::from((!lo & hi).count_ones());
                            counts[1] += u64::from((lo & !hi).count_ones());
                            counts[0] += u64::from((mask & !lo & !hi).count_ones());
                        }
                        counts
                    })
                })
                .collect();
            for handle in handles {
                let counts = handle.join().unwrap();
                for (sum, count) in total.iter_mut().zip(counts) {
                    *sum += count;
                }
            }
        });
        total
    }
}

/// The source tree this binary was built from, whose `tables/` holds the
/// `.hugemeta` files of tables on hugetlbfs (which only holds page-sized
/// files). Stored in a fixed-size buffer so that the binary's layout does not
/// depend on the length of the build path: otherwise builds from different
/// worktrees place all code at different offsets, which alone moves benchmark
/// results by 1-2%.
static BUILD_DIR: [u8; 256] = {
    let path = env!("CARGO_MANIFEST_DIR").as_bytes();
    assert!(path.len() < 256, "build path too long");
    let mut buf = [0u8; 256];
    let mut i = 0;
    while i < path.len() {
        buf[i] = path[i];
        i += 1;
    }
    buf
};

/// [`BUILD_DIR`] as a string (read through `black_box`, so the padded buffer
/// is what the binary contains, not a folded copy of the path).
fn build_dir() -> String {
    let buf: &[u8; 256] = std::hint::black_box(&BUILD_DIR);
    let len = buf.iter().position(|&b| b == 0).unwrap_or(buf.len());
    String::from_utf8_lossy(&buf[..len]).into_owned()
}

/// The meta file of a table file (for hugetlbfs files, which cannot hold
/// small files, in the repository's `tables` directory).
///
/// # Panics
/// If a hugetlbfs `path` has no file name.
#[must_use]
pub fn meta_path(path: &str) -> String {
    if path.starts_with("/mnt/huge") {
        let name = std::path::Path::new(path)
            .file_name()
            .unwrap()
            .to_string_lossy();
        format!("{}/tables/{name}.hugemeta", build_dir())
    } else {
        format!("{path}.meta")
    }
}

/// Write a table's `k` and `base`.
///
/// # Errors
/// If the meta file cannot be written.
pub fn write_meta(path: &str, meta: &H48Meta) -> std::io::Result<()> {
    std::fs::write(meta_path(path), format!("{} {}\n", meta.k, meta.base))
}

/// Read a table's `k` and `base`.
///
/// # Errors
/// If the meta file cannot be read, or does not hold `k <= 11` and a base
/// of at most 12: the search relies on bounds below 16 (`base + 3` and
/// 4-bit group minima) and on the index layout of `k`.
pub fn read_meta(path: &str) -> std::io::Result<H48Meta> {
    let text = std::fs::read_to_string(meta_path(path))?;
    let invalid = || {
        std::io::Error::new(
            std::io::ErrorKind::InvalidData,
            format!("bad table meta {text:?}"),
        )
    };
    let numbers: Vec<u32> = text
        .split_whitespace()
        .map(|x| x.parse().map_err(|_| invalid()))
        .collect::<Result<_, _>>()?;
    let [k, base] = numbers[..] else {
        return Err(invalid());
    };
    match (k, u8::try_from(base)) {
        (0..=11, Ok(base @ 0..=12)) => Ok(H48Meta { k, base }),
        _ => Err(invalid()),
    }
}

impl H48Table {
    /// Open a table file. Files on hugetlbfs are mapped directly (1GB pages);
    /// other files are copied into anonymous huge-page memory.
    ///
    /// # Errors
    /// If the table or its meta file cannot be read, or their sizes do not
    /// match.
    ///
    /// # Panics
    /// If reading a copied table fails half-way.
    pub fn open(path: &str) -> std::io::Result<H48Table> {
        let meta = read_meta(path)?;
        let len = usize::try_from(h48_bytes(meta.k)).map_err(std::io::Error::other)?;
        // A file of another `k` (a stale or wrong meta) would give wrong,
        // possibly too high, bounds: its size must match (hugetlbfs files
        // are rounded up to whole 1 GiB pages).
        let file_len = std::fs::metadata(path)?.len();
        if file_len < len as u64 || file_len >= len as u64 + (1 << 30) {
            return Err(std::io::Error::other(format!(
                "table file {path}: {file_len} bytes, but h{} needs {len}",
                meta.k
            )));
        }
        if path.contains("huge") || path.starts_with("/dev/shm") {
            let memory = Memory::map_file(path, len, false)?;
            return Ok(H48Table { memory, meta });
        }
        // Read in parallel (16 threads): a disk or page cache copy of tens
        // of GiB.
        let memory = Memory::anonymous(len);
        let file = std::fs::File::open(path)?;
        let threads = 16usize;
        let per_thread = len.div_ceil(threads);
        std::thread::scope(|s| {
            for t in 0..threads {
                let file = &file;
                let memory = &memory;
                s.spawn(move || {
                    use std::os::unix::fs::FileExt;
                    let start = t * per_thread;
                    let end = ((t + 1) * per_thread).min(len);
                    if start >= end {
                        return;
                    }
                    let buf = unsafe {
                        std::slice::from_raw_parts_mut(memory.ptr().add(start), end - start)
                    };
                    file.read_exact_at(buf, start as u64).expect("read table");
                });
            }
        });
        Ok(H48Table { memory, meta })
    }

    /// An all-zero table (every bound is then the corner depth), for unit
    /// tests with `Cocsep::truncated`.
    #[cfg(test)]
    pub(crate) fn zeroed(k: u32, base: u8) -> H48Table {
        H48Table {
            memory: Memory::anonymous(usize::try_from(h48_bytes(k)).unwrap()),
            meta: H48Meta { k, base },
        }
    }

    /// Write the table and its meta file.
    ///
    /// # Errors
    /// If a file cannot be written.
    pub fn save(&self, path: &str) -> std::io::Result<()> {
        let len = usize::try_from(h48_bytes(self.meta.k)).map_err(std::io::Error::other)?;
        std::fs::write(path, &self.memory.bytes()[..len])?;
        write_meta(path, &self.meta)
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::cubie::*;

    /// Tables open only with a valid meta and a file of the size its `k`
    /// needs (a wrong meta would give wrong, possibly too high, bounds).
    #[test]
    #[cfg_attr(miri, ignore = "files")]
    fn table_meta_and_size_are_checked() {
        let dir = std::env::temp_dir().join(format!("cubeopt-meta-{}", std::process::id()));
        std::fs::create_dir_all(&dir).unwrap();
        let path = dir.join("h0").to_string_lossy().into_owned();
        let len = h48_bytes(0);
        std::fs::write(&path, vec![0u8; usize::try_from(len).unwrap()]).unwrap();
        let open_with = |meta: &str| {
            std::fs::write(meta_path(&path), meta).unwrap();
            H48Table::open(&path).map(|t| (t.meta.k, t.meta.base))
        };
        assert_eq!(open_with("0 8\n").unwrap(), (0, 8));
        for bad in ["0 13", "12 8", "0", "0 8 1", "x 8", "0 -1", ""] {
            assert!(open_with(bad).is_err(), "meta {bad:?}");
        }
        // The file of an h0 table is too small for h1.
        assert!(open_with("1 8").is_err());
        std::fs::remove_dir_all(&dir).unwrap();
    }

    /// A table file opened for solving (hugetlbfs or /dev/shm) is mapped
    /// read-only.
    #[test]
    #[cfg_attr(miri, ignore = "files")]
    fn opened_table_file_is_read_only() {
        let path = format!("/dev/shm/cubeopt-test-{}-h0", std::process::id());
        let len = usize::try_from(h48_bytes(0)).unwrap();
        std::fs::write(&path, vec![0u8; len]).unwrap();
        std::fs::write(meta_path(&path), "0 8\n").unwrap();
        let table = H48Table::open(&path).unwrap();
        let start = table.ptr() as usize;
        let maps = std::fs::read_to_string("/proc/self/maps").unwrap();
        let perms = maps
            .lines()
            .find(|l| l.starts_with(&format!("{start:x}-")))
            .map(|l| l.split_whitespace().nth(1).unwrap().to_string());
        assert_eq!(perms.as_deref(), Some("r--s"), "{maps}");
        drop(table);
        std::fs::remove_file(meta_path(&path)).unwrap();
        std::fs::remove_file(&path).unwrap();
    }

    #[test]
    #[cfg_attr(miri, ignore = "Cocsep::generate is too slow under Miri")]
    fn cocsep_classes_and_distribution() {
        let cs = Cocsep::generate();
        assert_eq!(cs.representatives.len(), 3393);
        assert_eq!(
            &cs.distribution[..10],
            &[1, 6, 63, 468, 3068, 15438, 53814, 71352, 8784, 96]
        );
        // The cocsep class and depth are invariant under symmetry.
        let mut rng = Rng(7);
        for _ in 0..200 {
            let c = Cube::from_cubie(&CubieCube::random(&mut rng));
            let d0 = cs.entries[cocsep(c)];
            for t in 0..48 {
                let d1 = cs.entries[cocsep(c.transform(t))];
                assert_eq!(entry_class(d0), entry_class(d1));
                assert_eq!(entry_depth(d0), entry_depth(d1));
            }
            let p = cs.packed(cocsep(c));
            assert_eq!(packed_class(p), entry_class(d0));
            assert_eq!(packed_sym_to_rep(p), entry_sym_to_rep(d0));
            assert_eq!(packed_depth(p), entry_depth(d0));
            // sym_to_rep maps the cube's corners onto the representative.
            let r = cs.representatives[entry_class(d0)];
            assert_eq!(cocsep(c.transform(entry_sym_to_rep(d0))), cocsep(r));
        }
    }
}
